local PARENT = {["Torso"]="HumanoidRootPart",["Head"]="Torso",["Left Arm"]="Torso",["Right Arm"]="Torso",["Left Leg"]="Torso",["Right Leg"]="Torso"}
local seq = Instance.new("KeyframeSequence")
seq.Name = "NHG_StrafeRight_Square"
seq.Loop = true
seq.Priority = Enum.AnimationPriority.Core
for line in string.gmatch(DATA, "[^\n]+") do
	local t, rest = string.match(line, "^([^;]+);?(.*)$")
	local kf = Instance.new("Keyframe")
	kf.Time = tonumber(t)
	local poses = {}
	local function ensure(part)
		local p = poses[part]
		if p then return p end
		p = Instance.new("Pose")
		p.Name = part
		p.Weight = 0
		p.EasingStyle = Enum.PoseEasingStyle.Linear
		poses[part] = p
		local par = PARENT[part]
		p.Parent = if par then ensure(par) else kf
		return p
	end
	ensure("HumanoidRootPart")
	for part, vals in string.gmatch(rest, "([^=;]+)=([^;]+)") do
		local n = {}
		for v in string.gmatch(vals, "[^,]+") do table.insert(n, tonumber(v)) end
		local p = ensure(part)
		p.Weight = 1
		p.CFrame = CFrame.new(n[5] or 0, n[6] or 0, n[7] or 0, n[1], n[2], n[3], n[4])
	end
	kf.Parent = seq
end
local SS = game:GetService("ServerStorage")
local function folderAt(path)
	local node = SS
	for name in string.gmatch(path, "[^%.]+") do
		local nx = node:FindFirstChild(name)
		if not nx then nx = Instance.new("Folder") nx.Name = name nx.Parent = node end
		node = nx
	end
	return node
end
for _, path in { "NHGestures", "NHPublish.Gestures" } do
	local f = folderAt(path)
	local old = f:FindFirstChild(seq.Name)
	if old then old:Destroy() end
	seq:Clone().Parent = f
end
local RS = game:GetService("ReplicatedStorage") local lf = RS:FindFirstChild("NHLocoClips") or Instance.new("Folder") lf.Name = "NHLocoClips" lf.Parent = RS local o2 = lf:FindFirstChild(seq.Name) if o2 then o2:Destroy() end seq:Clone().Parent = lf -- Studio: the client registers it
seq:Destroy()
return string.format("built NHG_StrafeRight_Square (%d keyframes, %.3f s)", #SS.NHGestures:FindFirstChild("NHG_StrafeRight_Square"):GetKeyframes(), 1.033)
